1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Single source of truth for an owner's <em>identity</em>. All duplicate detection on the create
10	 * endpoint is expressed through one derived {@code identityKey}:
11	 *
12	 * <pre>identityKey = SHA-256 hex over (normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))</pre>
13	 *
14	 * <p>The result is the full 64-character lower-case hex SHA-256 digest. A new owner is a duplicate
15	 * (409) only when its whole {@code identityKey} equals an existing owner's — see
16	 * {@link CheckIdentityUnique}. Because the normalized telephone is part of the hashed input, two
17	 * members of the same household (same last name and postcode) with different telephones have
18	 * different keys and are both allowed; only an exact full-key match collides.
19	 *
20	 * <p>The {@code householdId} is a separate, stable identifier shared by owners living in the same
21	 * household (same normalized last name and postcode): the first 12 upper-cased hex characters of the
22	 * SHA-256 of {@code '<lastName>|<postcode>'}. {@link AssignHouseholdId} assigns it and
23	 * {@link org.springframework.samples.petclinic.mapper.OwnerMapper} returns it. It no longer drives
24	 * duplicate detection — a soft match (see {@link AssignPossibleDuplicate}) instead triggers when the
25	 * {@code identityKey} differs but {@code soundex(lastName)} and postcode match.
26	 */
27	public final class OwnerIdentity {
28	
29	    private OwnerIdentity() {
30	    }
31	
32	    /**
33	     * The shared {@code householdId} derived from the last name and postcode: the first 12 upper-cased
34	     * hex characters of SHA-256 of {@code '<lastName>|<postcode>'}, with the last name normalized
35	     * (lower-cased, runs of whitespace collapsed, trimmed) and a null/blank postcode contributing the
36	     * empty string. Because it is a pure function of {@code (lastName, postcode)}, two owners sharing
37	     * both deterministically receive the same value — they are, by definition, the same household.
38	     */
39	    public static String householdId(String lastName, String postcode) {
40	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode.trim());
41	        return shaHex(key, 12);
42	    }
43	
44	    /**
45	     * The derived {@code identityKey}: the full lower-case hex SHA-256 of
46	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A null telephone and a
47	     * blank/absent email each contribute the empty string.
48	     */
49	    public static String identityKey(String telephone, String email, String lastName) {
50	        String tel = telephone == null ? "" : telephone;
51	        String em = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
52	        String key = tel + "|" + em + "|" + soundex(lastName);
53	        return sha256Hex(key);
54	    }
55	
56	    /**
57	     * American Soundex code of {@code value}: the retained first letter followed by three digits.
58	     * Adjacent letters (or letters separated only by {@code h}/{@code w}) sharing a code are coded once;
59	     * a vowel between them keeps both. Non-letters are ignored and the result is right-padded with
60	     * zeros to length four. A null/letterless value contributes the empty string.
61	     */
62	    public static String soundex(String value) {
63	        if (value == null) {
64	            return "";
65	        }
66	        StringBuilder letters = new StringBuilder();
67	        for (int i = 0; i < value.length(); i++) {
68	            char c = value.charAt(i);
69	            if (Character.isLetter(c)) {
70	                letters.append(Character.toUpperCase(c));
71	            }
72	        }
73	        if (letters.length() == 0) {
74	            return "";
75	        }
76	        StringBuilder code = new StringBuilder();
77	        code.append(letters.charAt(0));
78	        char prev = soundexCode(letters.charAt(0));
79	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
80	            char c = letters.charAt(i);
81	            if (c == 'H' || c == 'W') {
82	                continue; // separators: leave prev unchanged so letters around them stay adjacent
83	            }
84	            char d = soundexCode(c);
85	            if (d != '0' && d != prev) {
86	                code.append(d);
87	            }
88	            prev = (d == '0') ? '0' : d; // a vowel (code 0) resets, so same codes across it are coded twice
89	        }
90	        while (code.length() < 4) {
91	            code.append('0');
92	        }
93	        return code.toString();
94	    }
95	
96	    /** Soundex digit for a letter; {@code '0'} for vowels and other uncoded letters. */
97	    private static char soundexCode(char c) {
98	        switch (c) {
99	            case 'B': case 'F': case 'P': case 'V':
100	                return '1';
101	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
102	                return '2';
103	            case 'D': case 'T':
104	                return '3';
105	            case 'L':
106	                return '4';
107	            case 'M': case 'N':
108	                return '5';
109	            case 'R':
110	                return '6';
111	            default:
112	                return '0';
113	        }
114	    }
115	
116	    /** Lower-cases and collapses runs of whitespace to a single space, trimmed. Used for last name. */
117	    private static String normalizeName(String value) {
118	        if (value == null) {
119	            return "";
120	        }
121	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
122	    }
123	
124	    /** First {@code n} upper-case hex characters of SHA-256 of {@code value}. */
125	    private static String shaHex(String value, int n) {
126	        return sha256(value, "%02X").substring(0, n);
127	    }
128	
129	    /** Full lower-case hex SHA-256 of {@code value}. */
130	    private static String sha256Hex(String value) {
131	        return sha256(value, "%02x");
132	    }
133	
134	    private static String sha256(String value, String byteFormat) {
135	        try {
136	            byte[] digest = MessageDigest.getInstance("SHA-256")
137	                    .digest(value.getBytes(StandardCharsets.UTF_8));
138	            StringBuilder sb = new StringBuilder(digest.length * 2);
139	            for (byte b : digest) {
140	                sb.append(String.format(byteFormat, b));
141	            }
142	            return sb.toString();
143	        }
144	        catch (NoSuchAlgorithmException e) {
145	            throw new IllegalStateException("SHA-256 not available", e);
146	        }
147	    }
148	}
