1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The single duplicate check for the create-owner endpoint. It rejects (409) when a new owner's
11	 * derived {@code identityKey} — the SHA-256 hex of {@code normalizedTelephone|lowerEmail|soundex(lastName)}
12	 * (see {@link OwnerIdentity}, also returned on the owner) — equals an existing owner's. This is now the
13	 * only hard-duplicate check: the former separate household-duplicate block no longer applies.
14	 *
15	 * <p>Because the normalized telephone is part of the hashed key, two owners sharing a last name and
16	 * postcode but with different telephones have different keys and both create (the second flagged a soft
17	 * match, see {@link AssignPossibleDuplicate}) — a change from the former household check, which rejected
18	 * them regardless of telephone. Soft-deleted owners are ignored, and the email-domain blocklist has
19	 * already run in {@link ValidateOwnerFields} (a rejected email is a 400 before this check).
20	 *
21	 * <p>Runs after {@link ValidateOwnerFields} has normalized the telephone (E.164) and email
22	 * (lower-cased), and within the write transaction so the check and the insert see one consistent view.
23	 */
24	public class CheckIdentityUnique {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String identityKey = OwnerIdentity.identityKey(
29	                request.getTelephone(), request.getEmail(), request.getLastName());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (Boolean.TRUE.equals(existing.getDeleted())) {
32	                continue; // soft-deleted owners are ignored by the identity check
33	            }
34	            String existingKey = OwnerIdentity.identityKey(
35	                    existing.getTelephone(), existing.getEmail(), existing.getLastName());
36	            if (identityKey.equals(existingKey)) {
37	                throw new DuplicateIdentityException(identityKey);
38	            }
39	        }
40	    }
41	}
