1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Map;
15	import java.util.Set;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
24	    @Mapping(target = "displayName",
25	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
26	    @Mapping(target = "initials",
27	            expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
28	                    + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
29	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
30	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
31	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
32	    @Mapping(target = "membershipPoints", expression = "java(OwnerMapper.membershipPoints(owner))")
33	    @Mapping(target = "membershipLevel", expression = "java(OwnerMapper.membershipLevel(owner))")
34	    @Mapping(target = "locality", expression = "java(locality(owner))")
35	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
37	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
38	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
41	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * Derives the owner's {@code selfLink}: the canonical relative URL of this owner, formatted
46	     * {@code '/api/owners/<id>'}. Returns {@code null} when the id is absent, so owners without an
47	     * id map cleanly.
48	     */
49	    default String selfLink(Owner owner) {
50	        if (owner.getId() == null) {
51	            return null;
52	        }
53	        return "/api/owners/" + owner.getId();
54	    }
55	
56	    /**
57	     * The calendar year in which the fiscal year containing {@code date} ends. The fiscal year runs
58	     * from 1 July to 30 June, so a date on or after 1 July belongs to the fiscal year ending the
59	     * following calendar year (e.g. 15 Aug 2026 falls in the fiscal year ending 2027). All fiscal-year
60	     * derived values — {@link #fiscalYear(Owner)}, the {@link #membershipNumber(Owner)} year segment and
61	     * the tenure bonus in {@link #membershipPoints(Owner)} — go through this single definition.
62	     */
63	    static int fiscalYearEnding(java.time.LocalDate date) {
64	        int year = date.getYear();
65	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? year + 1 : year;
66	    }
67	
68	    /**
69	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'} where YY is the last two
70	     * digits of the fiscal year (starting 1 July) that contains the business-day-adjusted
71	     * {@code registrationDate} — so 15 Aug 2026 yields {@code 'FY27'}. Returns {@code null} when the
72	     * registrationDate is absent, so owners without one map cleanly.
73	     */
74	    default String fiscalYear(Owner owner) {
75	        if (owner.getRegistrationDate() == null) {
76	            return null;
77	        }
78	        return String.format("FY%02d", fiscalYearEnding(owner.getRegistrationDate()) % 100);
79	    }
80	
81	    /**
82	     * The fixed set of known regions (localities) treated as METRO; any other locality
83	     * (including 'UNKNOWN') is REGIONAL.
84	     */
85	    Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
86	
87	    /**
88	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
89	     * {@code 'PREMIUM'} when {@link #membershipLevel(Owner)} is 3 or more, otherwise
90	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the {@link #locality(Owner)} is a known
91	     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'} — so the result is one of
92	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
93	     * {@code 'STANDARD_REGIONAL'}.
94	     */
95	    default String ownerSegment(Owner owner) {
96	        Integer level = membershipLevel(owner);
97	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
98	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
99	        return tier + "_" + area;
100	    }
101	
102	    /**
103	     * Derives the owner's {@code salutation}: the {@code title} and {@code lastName} joined by a
104	     * single space ({@code '<title> <lastName>'}) when a title is present, otherwise just the
105	     * {@code lastName}. So an owner titled 'DR' named 'Who' yields {@code 'DR Who'}.
106	     */
107	    default String salutation(Owner owner) {
108	        String title = owner.getTitle();
109	        if (title == null || title.isBlank()) {
110	            return owner.getLastName();
111	        }
112	        return title + " " + owner.getLastName();
113	    }
114	
115	    /**
116	     * Derives the owner's {@code ageBand} from {@code birthDate}, computed against the
117	     * {@code registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64 and
118	     * {@code 'SENIOR'} at 65 or over. Returns {@code null} when either date is absent, so owners
119	     * without a birthDate map cleanly.
120	     */
121	    default String ageBand(Owner owner) {
122	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
123	            return null;
124	        }
125	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
126	        if (age < 18) {
127	            return "MINOR";
128	        }
129	        if (age < 65) {
130	            return "ADULT";
131	        }
132	        return "SENIOR";
133	    }
134	
135	    /**
136	     * Derives the owner's {@code identityKey}, the single key all duplicate detection is expressed
137	     * through: the SHA-256 hex of {@code normalizedTelephone|lowerEmail|soundex(lastName)}
138	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity}).
139	     */
140	    default String identityKey(Owner owner) {
141	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity
142	                .identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
143	    }
144	
145	    /**
146	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
147	     * humans as the country code, a space, then the national digits grouped left-to-right in threes
148	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The known country codes are
149	     * {@code +61} (2 digits, matching the normalization in
150	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerFields}) and
151	     * {@code +1} (1 digit); any other leading digit is treated as a two-digit country code. Returns
152	     * {@code null} when the telephone is absent or not a {@code +}-prefixed run of digits, so the raw
153	     * {@code telephone} is left untouched in E.164 form.
154	     */
155	    default String telephoneDisplay(Owner owner) {
156	        String telephone = owner.getTelephone();
157	        if (telephone == null || !telephone.startsWith("+")) {
158	            return null;
159	        }
160	        String digits = telephone.substring(1);
161	        if (!digits.matches("\\d+")) {
162	            return null;
163	        }
164	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
165	        if (digits.length() <= countryCodeLength) {
166	            return null;
167	        }
168	        String countryCode = digits.substring(0, countryCodeLength);
169	        String national = digits.substring(countryCodeLength);
170	        StringBuilder grouped = new StringBuilder();
171	        for (int i = 0; i < national.length(); i++) {
172	            if (i > 0 && i % 3 == 0) {
173	                grouped.append(' ');
174	            }
175	            grouped.append(national.charAt(i));
176	        }
177	        return "+" + countryCode + " " + grouped;
178	    }
179	
180	    /**
181	     * Fixed region-to-timezone table mapping each locality (region) to its IANA timezone name.
182	     */
183	    Map<String, String> REGION_TIMEZONE = Map.of(
184	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
185	
186	    /**
187	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's {@link #locality(Owner)}
188	     * (region) from the fixed region-to-timezone table (NSW→Australia/Sydney, VIC→Australia/Melbourne,
189	     * QLD→Australia/Brisbane). Returns {@code null} when the locality is not in the table (e.g. 'UNKNOWN'),
190	     * so owners outside the known regions map cleanly.
191	     */
192	    default String timezone(Owner owner) {
193	        return REGION_TIMEZONE.get(locality(owner));
194	    }
195	
196	    /**
197	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
198	     * otherwise {@code 'PHONE'}.
199	     */
200	    default String contactPreference(Owner owner) {
201	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
202	        return hasEmail ? "EMAIL" : "PHONE";
203	    }
204	
205	    /**
206	     * Derives the owner's locality (region) from the region-and-hash {@code customerCode}: it is the
207	     * {@code REGION} prefix of {@code '<REGION>-<HASH8>'} (see
208	     * {@link org.springframework.samples.petclinic.rest.function.owner.CustomerCode}). When the code is
209	     * absent it falls back to computing the region directly from the postcode range (NSW 2000-2099,
210	     * VIC 3000-3099, QLD 4000-4099) then the city table, yielding {@code 'UNKNOWN'} when neither
211	     * resolves. Sharing the region with the identity keeps locality and customerCode consistent.
212	     */
213	    default String locality(Owner owner) {
214	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCode
215	                .regionOf(owner.getCustomerCode());
216	        if (region != null) {
217	            return region;
218	        }
219	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCode
220	                .region(owner.getPostcode(), owner.getCity());
221	    }
222	
223	    /**
224	     * Derives the owner's membership points: starting at 0, plus 2 when an email is present, plus 1
225	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more (its
226	     * {@code householdMemberCount}), plus 3 when the owner's tenure — the number of fiscal years
227	     * (starting 1 July) elapsed between {@code registrationDate} and today — exceeds 1.
228	     */
229	    static Integer membershipPoints(Owner owner) {
230	        return membershipPoints(owner, owner.getHouseholdMemberCount());
231	    }
232	
233	    /**
234	     * As {@link #membershipPoints(Owner)}, but scoring the "household of 3 or more" bonus against the
235	     * supplied {@code householdMemberCount} rather than the owner's stored one. Used when evaluating an
236	     * existing household member against the household as it stands <em>now</em> (see
237	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}), since a
238	     * member's own count is frozen at its own create time.
239	     */
240	    static Integer membershipPoints(Owner owner, Integer householdMemberCount) {
241	        int points = 0;
242	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
243	        if (hasEmail) {
244	            points += 2;
245	        }
246	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
247	        if (noNamesakes) {
248	            points += 1;
249	        }
250	        boolean largeHousehold = householdMemberCount != null && householdMemberCount >= 3;
251	        if (largeHousehold) {
252	            points += 2;
253	        }
254	        boolean tenured = owner.getRegistrationDate() != null
255	                && (fiscalYearEnding(java.time.LocalDate.now())
256	                        - fiscalYearEnding(owner.getRegistrationDate())) > 1;
257	        if (tenured) {
258	            points += 3;
259	        }
260	        return points;
261	    }
262	
263	    /**
264	     * The owner's effective membership level. When a level has been stored on the entity (assigned at
265	     * create time by
266	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}, which
267	     * applies the household level ceiling) that value stands; otherwise it falls back to the level
268	     * derived directly from points (see {@link #derivedMembershipLevel(Owner)}), so seed owners
269	     * without a stored level still map cleanly.
270	     */
271	    static Integer membershipLevel(Owner owner) {
272	        if (owner.getMembershipLevel() != null) {
273	            return owner.getMembershipLevel();
274	        }
275	        return derivedMembershipLevel(owner);
276	    }
277	
278	    /**
279	     * Derives the owner's membership level from 1 to 4 by mapping {@link #membershipPoints(Owner)}:
280	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. This is the uncapped level, before
281	     * the household ceiling applied at create time.
282	     */
283	    static Integer derivedMembershipLevel(Owner owner) {
284	        return levelForPoints(membershipPoints(owner));
285	    }
286	
287	    /**
288	     * As {@link #derivedMembershipLevel(Owner)}, but scoring the household bonus against the supplied
289	     * {@code householdMemberCount} — the household's current size — rather than the owner's frozen one.
290	     */
291	    static Integer derivedMembershipLevel(Owner owner, Integer householdMemberCount) {
292	        return levelForPoints(membershipPoints(owner, householdMemberCount));
293	    }
294	
295	    private static Integer levelForPoints(int points) {
296	        if (points >= 6) {
297	            return 4;
298	        }
299	        if (points >= 4) {
300	            return 3;
301	        }
302	        if (points >= 2) {
303	            return 2;
304	        }
305	        return 1;
306	    }
307	
308	    /**
309	     * Derives the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
310	     * last two digits of the fiscal year (starting 1 July) that contains the registrationDate — the
311	     * same year segment as {@link #fiscalYear(Owner)} (e.g. {@code 'NSW-1A2B3C4D-M27'} for a
312	     * registrationDate of 15 Aug 2026). Returns {@code null} when either source field is absent, so
313	     * owners without a customerCode or registrationDate map cleanly.
314	     */
315	    default String membershipNumber(Owner owner) {
316	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
317	            return null;
318	        }
319	        return owner.getCustomerCode() + "-M"
320	                + String.format("%02d", fiscalYearEnding(owner.getRegistrationDate()) % 100);
321	    }
322	
323	    /**
324	     * Derives the owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
325	     * digits contained in the {@code customerCode}. Returns {@code null} when the customerCode is
326	     * absent, so owners without a customerCode map cleanly.
327	     */
328	    default Integer checkDigit(Owner owner) {
329	        String customerCode = owner.getCustomerCode();
330	        if (customerCode == null) {
331	            return null;
332	        }
333	        int sum = 0;
334	        boolean dbl = true;
335	        for (int i = customerCode.length() - 1; i >= 0; i--) {
336	            char c = customerCode.charAt(i);
337	            if (c < '0' || c > '9') {
338	                continue;
339	            }
340	            int d = c - '0';
341	            if (dbl) {
342	                d *= 2;
343	                if (d > 9) {
344	                    d -= 9;
345	                }
346	            }
347	            sum += d;
348	            dbl = !dbl;
349	        }
350	        return (10 - (sum % 10)) % 10;
351	    }
