3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import tools.jackson.databind.ObjectMapper;
10	import org.springframework.samples.petclinic.mapper.OwnerMapper;
11	import org.springframework.samples.petclinic.model.Owner;
12	
13	/**
14	 * Emits the audit for a newly created owner via the dedicated {@code AUDIT} logger. Two lines:
15	 *
16	 * <ol>
17	 *   <li>the human-readable audit line carrying the owner's id, customerCode, registrationDate,
18	 *       membershipLevel and membershipNumber; and</li>
19	 *   <li>an immutable structured {@link OwnerCreatedEvent} as one JSON line
20	 *       ({@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}), where
21	 *       {@code seq} increases monotonically across creates and {@code customerCode} carries the
22	 *       owner's current {@linkplain #primaryIdentifier(Owner) primary identifier}.</li>
23	 * </ol>
24	 *
25	 * <p>Runs after {@link SaveOwner} so the generated id is present, within the same write
26	 * transaction as the insert.
27	 */
28	public class AuditOwnerCreated {
29	
30	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
31	
32	    /** Process-wide, monotonically increasing sequence stamped on each {@link OwnerCreatedEvent}. */
33	    private static final AtomicLong SEQ = new AtomicLong();
34	
35	    private static final ObjectMapper JSON = new ObjectMapper();
36	
37	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
38	        AUDIT.info(
39	                "Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
40	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
41	                OwnerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
42	
43	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
44	                primaryIdentifier(owner), OwnerMapper.membershipLevel(owner));
45	        AUDIT.info(JSON.writeValueAsString(event));
46	    }
47	
48	    /**
49	     * The owner's current primary identifier carried by the structured event. Today this is the
50	     * {@code customerCode}; when the customerCode is later unified into the memberId, change this
51	     * single accessor so every {@code OWNER_CREATED} event carries the memberId instead.
52	     */
53	    private static String primaryIdentifier(Owner owner) {
54	        return owner.getCustomerCode();
55	    }
56	}
