44	    /**
45	     * Derives the owner's {@code selfLink}: the canonical relative URL of this owner, formatted
46	     * {@code '/api/owners/<id>'}. Returns {@code null} when the id is absent, so owners without an
47	     * id map cleanly.
48	     */
49	    default String selfLink(Owner owner) {
50	        if (owner.getId() == null) {
51	            return null;
52	        }
53	        return "/api/owners/" + owner.getId();
