115	    /**
116	     * Derives the owner's {@code ageBand} from {@code birthDate}, computed against the
117	     * {@code registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64 and
118	     * {@code 'SENIOR'} at 65 or over. Returns {@code null} when either date is absent, so owners
119	     * without a birthDate map cleanly.
120	     */
121	    default String ageBand(Owner owner) {
122	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
123	            return null;
124	        }
125	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
126	        if (age < 18) {
127	            return "MINOR";
128	        }
129	        if (age < 65) {
130	            return "ADULT";
131	        }
132	        return "SENIOR";
133	    }
