137	     * through: the SHA-256 hex of {@code normalizedTelephone|lowerEmail|soundex(lastName)}
138	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity}).
139	     */
140	    default String identityKey(Owner owner) {
141	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity
142	                .identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
143	    }
144	
145	    /**
146	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
147	     * humans as the country code, a space, then the national digits grouped left-to-right in threes
148	     * (e.g. {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The known country codes are
149	     * {@code +61} (2 digits, matching the normalization in
150	     * {@link org.springframework.samples.petclinic.rest.function.owner.ValidateOwnerFields}) and
151	     * {@code +1} (1 digit); any other leading digit is treated as a two-digit country code. Returns
152	     * {@code null} when the telephone is absent or not a {@code +}-prefixed run of digits, so the raw
153	     * {@code telephone} is left untouched in E.164 form.
154	     */
155	    default String telephoneDisplay(Owner owner) {
156	        String telephone = owner.getTelephone();
157	        if (telephone == null || !telephone.startsWith("+")) {
158	            return null;
159	        }
160	        String digits = telephone.substring(1);
161	        if (!digits.matches("\\d+")) {
162	            return null;
163	        }
164	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
165	        if (digits.length() <= countryCodeLength) {
166	            return null;
167	        }
168	        String countryCode = digits.substring(0, countryCodeLength);
169	        String national = digits.substring(countryCodeLength);
170	        StringBuilder grouped = new StringBuilder();
171	        for (int i = 0; i < national.length(); i++) {
172	            if (i > 0 && i % 3 == 0) {
173	                grouped.append(' ');
174	            }
175	            grouped.append(national.charAt(i));
