177	        return "+" + countryCode + " " + grouped;
178	    }
179	
180	    /**
181	     * Fixed region-to-timezone table mapping each locality (region) to its IANA timezone name.
182	     */
183	    Map<String, String> REGION_TIMEZONE = Map.of(
