220	                .region(owner.getPostcode(), owner.getCity());
221	    }
222	
223	    /**
224	     * Derives the owner's membership points: starting at 0, plus 2 when an email is present, plus 1
225	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more (its
226	     * {@code householdMemberCount}), plus 3 when the owner's tenure — the number of fiscal years
227	     * (starting 1 July) elapsed between {@code registrationDate} and today — exceeds 1.
228	     */
229	    static Integer membershipPoints(Owner owner) {
230	        return membershipPoints(owner, owner.getHouseholdMemberCount());
231	    }
232	
233	    /**
234	     * As {@link #membershipPoints(Owner)}, but scoring the "household of 3 or more" bonus against the
235	     * supplied {@code householdMemberCount} rather than the owner's stored one. Used when evaluating an
236	     * existing household member against the household as it stands <em>now</em> (see
237	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}), since a
238	     * member's own count is frozen at its own create time.
239	     */
240	    static Integer membershipPoints(Owner owner, Integer householdMemberCount) {
241	        int points = 0;
242	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
243	        if (hasEmail) {
244	            points += 2;
245	        }
246	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
247	        if (noNamesakes) {
248	            points += 1;
249	        }
250	        boolean largeHousehold = householdMemberCount != null && householdMemberCount >= 3;
251	        if (largeHousehold) {
252	            points += 2;
253	        }
254	        boolean tenured = owner.getRegistrationDate() != null
255	                && (fiscalYearEnding(java.time.LocalDate.now())
256	                        - fiscalYearEnding(owner.getRegistrationDate())) > 1;
257	        if (tenured) {
258	            points += 3;
259	        }
260	        return points;
261	    }
262	
263	    /**
264	     * The owner's effective membership level. When a level has been stored on the entity (assigned at
265	     * create time by
266	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}, which
267	     * applies the household level ceiling) that value stands; otherwise it falls back to the level
268	     * derived directly from points (see {@link #derivedMembershipLevel(Owner)}), so seed owners
269	     * without a stored level still map cleanly.
270	     */
271	    static Integer membershipLevel(Owner owner) {
272	        if (owner.getMembershipLevel() != null) {
273	            return owner.getMembershipLevel();
274	        }
275	        return derivedMembershipLevel(owner);
276	    }
277	
278	    /**
279	     * Derives the owner's membership level from 1 to 4 by mapping {@link #membershipPoints(Owner)}:
280	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. This is the uncapped level, before
281	     * the household ceiling applied at create time.
282	     */
283	    static Integer derivedMembershipLevel(Owner owner) {
284	        return levelForPoints(membershipPoints(owner));
285	    }
286	
287	    /**
288	     * As {@link #derivedMembershipLevel(Owner)}, but scoring the household bonus against the supplied
289	     * {@code householdMemberCount} — the household's current size — rather than the owner's frozen one.
290	     */
291	    static Integer derivedMembershipLevel(Owner owner, Integer householdMemberCount) {
292	        return levelForPoints(membershipPoints(owner, householdMemberCount));
293	    }
294	
295	    private static Integer levelForPoints(int points) {
296	        if (points >= 6) {
297	            return 4;
298	        }
299	        if (points >= 4) {
300	            return 3;
301	        }
302	        if (points >= 2) {
303	            return 2;
304	        }
305	        return 1;
306	    }
307	
308	    /**
309	     * Derives the owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
310	     * last two digits of the fiscal year (starting 1 July) that contains the registrationDate — the
311	     * same year segment as {@link #fiscalYear(Owner)} (e.g. {@code 'NSW-1A2B3C4D-M27'} for a
312	     * registrationDate of 15 Aug 2026). Returns {@code null} when either source field is absent, so
313	     * owners without a customerCode or registrationDate map cleanly.
314	     */
315	    default String membershipNumber(Owner owner) {
316	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
317	            return null;
318	        }
319	        return owner.getCustomerCode() + "-M"
320	                + String.format("%02d", fiscalYearEnding(owner.getRegistrationDate()) % 100);
321	    }
322	
323	    /**
324	     * Derives the owner's {@code checkDigit}: a single Luhn check digit (0-9) computed over the
325	     * digits contained in the {@code customerCode}. Returns {@code null} when the customerCode is
326	     * absent, so owners without a customerCode map cleanly.
327	     */
328	    default Integer checkDigit(Owner owner) {
329	        String customerCode = owner.getCustomerCode();
330	        if (customerCode == null) {
331	            return null;
332	        }
333	        int sum = 0;
334	        boolean dbl = true;
335	        for (int i = customerCode.length() - 1; i >= 0; i--) {
336	            char c = customerCode.charAt(i);
337	            if (c < '0' || c > '9') {
338	                continue;
339	            }
340	            int d = c - '0';
341	            if (dbl) {
342	                d *= 2;
343	                if (d > 9) {
344	                    d -= 9;
345	                }
346	            }
347	            sum += d;
348	            dbl = !dbl;
349	        }
350	        return (10 - (sum % 10)) % 10;
351	    }
352	
353	    Owner toOwner(OwnerDto ownerDto);
354	
355	    @Mapping(target = "id", ignore = true)
356	    @Mapping(target = "pets", ignore = true)
357	    @Mapping(target = "customerCode", ignore = true)
358	    @Mapping(target = "householdId", ignore = true)
359	    @Mapping(target = "namesakeCount", ignore = true)
360	    @Mapping(target = "householdMemberCount", ignore = true)
361	    @Mapping(target = "possibleDuplicate", ignore = true)
362	    @Mapping(target = "possibleDuplicateOf", ignore = true)
363	    @Mapping(target = "membershipLevel", ignore = true)
364	    @Mapping(target = "deleted", ignore = true)
365	    Owner toOwner(OwnerFieldsDto ownerDto);
366	
367	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
368	
369	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
370	
371	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
372	        OwnerPageDto ownerPageDto = new OwnerPageDto();
373	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
374	        ownerPageDto.setPage(ownerPage.getNumber());
375	        ownerPageDto.setSize(ownerPage.getSize());
376	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
377	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
378	        return ownerPageDto;
379	    }
380	}
